-- The books are append-only: the role the API runs as can read and insert ledger rows but never change or remove one.
-- A correction is a reversal plus a new posting (apps/api/src/modules/ledgerRules.ts `repost`).
REVOKE UPDATE, DELETE, TRUNCATE ON "ledger_entries" FROM app_user;
--> statement-breakpoint
-- A voucher's debits must equal its credits. Deferred, so a voucher's lines can be inserted one after another and the
-- check runs once at commit; a voucher that does not balance aborts the whole transaction, document included.
CREATE FUNCTION ledger_check_voucher() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE d numeric; c numeric;
BEGIN
  SELECT coalesce(sum(debit), 0), coalesce(sum(credit), 0) INTO d, c
    FROM ledger_entries WHERE org_id = NEW.org_id AND voucher_id = NEW.voucher_id;
  IF d <> c THEN
    RAISE EXCEPTION 'ledger voucher % is not balanced (debit %, credit %)', NEW.voucher_id, d, c USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END
$fn$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER ledger_voucher_balanced AFTER INSERT ON "ledger_entries"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ledger_check_voucher();
